      <h2 id="controlTitle">改变货物质量</h2><div class="muted">拖动滑块，或用方向键微调</div>
      <div class="big-number"><output id="cargoOutput">300</output><span>kg 货物</span></div>
      <div class="range-wrap"><div class="range-label"><label for="cargo">货物质量</label><span>0–1000 kg</span></div><input id="cargo" type="range" min="0" max="1000" step="10" value="300" aria-describedby="rangeHelp"><div id="rangeHelp" class="ticks"><span>空载</span><span>船口边界：800 kg</span><span>1000 kg</span></div></div>
      <div class="presets" aria-label="快速查看"><button type="button" data-value="0">空载</button><button type="button" data-value="800">刚到边界</button><button type="button" data-value="900">超过边界</button></div>
      <div class="metrics">
        <div class="metric"><span>船体自重</span><strong>200 kg</strong></div>
        <div class="metric"><span>船 + 货物总质量</span><strong id="total">500 kg</strong></div>
        <div class="metric"><span id="draftMetricLabel">静态吃水 d</span><strong id="draft">0.25 m</strong></div>
        <div class="metric"><span>距船口余量</span><strong id="margin">0.25 m</strong></div>
        <div class="metric"><span>边界总质量</span><strong>1000 kg</strong></div>
      </div>
    </section>
  </div>
  <section class="card explain">
    <h2>为什么水线会上升？</h2>
    <p>漂浮平衡时，浮力等于船和货物的总重量。船越重，就必须排开越多水；在这个箱形船模型里，更多排水量表现为更深的吃水。</p>
    <div class="formula">d = m ÷ (ρA)</div>
    <p>当吃水达到船口高度，船就到达这个模型的边界。再加货物，公式算出的深度会超过船高；这表示原先的“封闭船体静态漂浮”条件已不成立，不能把超出的数字当成真实吃水。</p>
    <div class="assumptions" aria-label="模型设定">
      <div><b>A = 2 m²</b>水平截面积</div><div><b>H = 0.5 m</b>船口离船底</div><div><b>ρ = 1000 kg/m³</b>水的密度</div><div><b>船体 = 200 kg</b>自重固定</div>
    </div>
    <div class="foot">这是刚性、直立、不漏水、无波浪的长方形船体模型。真实船的安全载荷还受船形、稳性、浪况、进水口位置等影响；本图不用于判断真实船舶载荷。平衡关系参考：得克萨斯大学浮体平衡讲义（Farside）。</div>
  </section>
  <div class="sr-only" id="liveResult" aria-live="polite"></div>
</main>
<script>
(() => {
 const A=2,H=0.5,rho=1000,hullMass=200;
 const slider=document.getElementById('cargo');
 const cargoOut=document.getElementById('cargoOutput'),totalEl=document.getElementById('total'),draftEl=document.getElementById('draft'),marginEl=document.getElementById('margin');
 const waterFill=document.getElementById('waterFill'),waterLine=document.getElementById('waterLine'),waterLabel=document.getElementById('waterLabel'),draftLabel=document.getElementById('draftLabel');
 const status=document.getElementById('status'),statusText=document.getElementById('statusText'),overMarker=document.getElementById('overMarker'),draftMetricLabel=document.getElementById('draftMetricLabel');
 const bottomY=311,topY=130,pixelH=bottomY-topY;
 const fmt=n=>Number.isInteger(n)?String(n):n.toFixed(2);
 function update(){
   const cargo=Number(slider.value),mass=hullMass+cargo,d=mass/(rho*A),atEdge=Math.abs(d-H)<1e-9,over=d>H;
   const visibleD=Math.min(d,H),waterY=bottomY-(visibleD/H)*pixelH;
   cargoOut.value=cargo;cargoOut.textContent=cargo;totalEl.textContent=mass+' kg';
   draftMetricLabel.textContent=over?'模型不报告实际吃水':'静态吃水 d';
   draftEl.textContent=over?'超出船口':fmt(d)+' m';
   marginEl.textContent=over?'超出 '+fmt(d-H)+' m':atEdge?'0 m（到边界）':fmt(H-d)+' m';
   waterFill.setAttribute('y',waterY);waterFill.setAttribute('height',bottomY-waterY);
   waterLine.setAttribute('d',`M75 ${waterY} H525`);waterLabel.setAttribute('y',waterY-11);
   draftLabel.textContent=over?'到船口':`吃水 ${fmt(d)} m`;draftLabel.setAttribute('y',Math.max(topY+18,(waterY+bottomY)/2));
   overMarker.style.display=over?'':'none';
   status.className='status '+(over?'over':atEdge?'edge':'safe');
   if(over){statusText.innerHTML=`超过船口边界<small>总质量 ${mass} kg 已大于边界 1000 kg；静态漂浮模型到此停止，图中水线停在船口。</small>`}
   else if(atEdge){statusText.innerHTML='刚好到达船口边界<small>吃水等于 0.5 m，船口余量为零；再加货物就超出模型边界。</small>'}
   else{statusText.innerHTML='稳定漂浮范围内<small>浮力与总重量平衡；增加货物会让吃水加深。</small>'}
   document.getElementById('svgDesc').textContent=over?'模型边界已超出，示意水线停在船口；红色虚线表示公式外推比较，不是实际水线。':atEdge?'水线恰好到达船口，船口余量为零。':`船体在水中漂浮，静态吃水约 ${fmt(d)} 米，水面低于船口。`;
 }
 slider.addEventListener('input',update);
 document.querySelectorAll('[data-value]').forEach(button=>button.addEventListener('click',()=>{slider.value=button.dataset.value;update();slider.focus()}));
 update();
})();
</script>
</body>
